#ifndef PRIORITY_QUEUE_H
#define PRIORITY_QUEUE_H

#include <string>
#include <vector>

// Forward declaration
struct Wolf;

// We'll define a generic function type to avoid needing complete Wolf type in header
#include <functional>

struct Event {
    std::string name;
    int priority; // 1-3, lower is more urgent
    std::string description;

    // Use a generic function that takes void* and cast inside implementation
    void (*effect)(void*); // Function to apply effect to Wolf object

    bool operator>(const Event& other) const {
        return priority > other.priority;
    }
    bool operator<(const Event& other) const {
        return priority < other.priority;
    }
};

class PriorityQueue {
private:
    std::vector<Event> heap;
    void heapifyUp(int index);
    void heapifyDown(int index);
public:
    void insert(Event e);
    Event extractMin();
    bool isEmpty();
};

#endif

#include "../include/priority_queue.h"
#include <stdexcept>

void PriorityQueue::heapifyUp(int index) {
    while (index > 0) {
        int parent = (index - 1) / 2;
        if (heap[index].priority > heap[parent].priority) break;
        std::swap(heap[index], heap[parent]);
        index = parent;
    }
}

void PriorityQueue::heapifyDown(int index) {
    int size = heap.size();
    while (true) {
        int left = 2 * index + 1;
        int right = 2 * index + 2;
        int smallest = index;
        if (left < size && heap[left].priority < heap[smallest].priority) smallest = left;
        if (right < size && heap[right].priority < heap[smallest].priority) smallest = right;
        if (smallest == index) break;
        std::swap(heap[index], heap[smallest]);
        index = smallest;
    }
}

void PriorityQueue::insert(Event e) {
    heap.push_back(e);
    heapifyUp(heap.size() - 1);
}

Event PriorityQueue::extractMin() {
    if (heap.empty()) throw std::runtime_error("Heap is empty");
    Event min = heap[0];
    heap[0] = heap.back();
    heap.pop_back();
    if (!heap.empty()) heapifyDown(0);
    return min;
}

bool PriorityQueue::isEmpty() {
    return heap.empty();
}

