        loadFile >> nodeId;

        // Find the node in the tree (this requires a function to find node by ID)
        // For now, we'll just reset the tree to root and the player will have to navigate back
        tree.buildSampleTree(); // Rebuild tree to ensure it's populated
        // We'll need to find the node with the saved ID
        // This requires a helper function in DecisionTree class
        // For now, we'll just go to the root node
        tree.setCurrentNode(tree.getRoot());

        // Clear current inventory
        Item* current = inventory.getHead();
        while (current) {
            Item* next = current->next;
            delete current;
            current = next;
        }
        inventory = Inventory(); // Reset inventory

        // Load inventory
        int itemCount;
        loadFile >> itemCount;
        for (int i = 0; i < itemCount; i++) {
            std::string name;
            ItemType type;
            int effect, quantity;

            loadFile >> name;
            loadFile >> type;
            loadFile >> effect;
            loadFile >> quantity;

            inventory.addItem(name, type, effect, quantity);
        }

        // Clear current pack
        PackMember* currentMember = pack.getHead();
        while (currentMember) {
            PackMember* next = currentMember->next;
            delete currentMember;
            currentMember = next;
        }
        pack = Pack(); // Reset pack

        // Load pack
        int memberCount;
        loadFile >> memberCount;
        for (int i = 0; i < memberCount; i++) {
            std::string name, role;
            int loyalty;

            loadFile >> name >> role >> loyalty;

            pack.addMember(name, role, loyalty);
        }

        loadFile.close();
        std::cout << "Game loaded successfully!" << std::endl;
    } else {
        std::cout << "Error: Could not open save file." << std::endl;
    }
}

