{"content":"#include <iostream>
#include <set>
#include <vector>
#include "../include/decision_tree.h"

class DecisionTreeValidator {
private:
    std::set<int> visitedNodes;
    std::vector<int> endingsFound;

    void traverseTree(DecisionNode* node) {
        if (!node) return;

        // Mark node as visited
        visitedNodes.insert(node->scenarioID);

        // If it's an ending, record it
        if (node->isEnding) {
            endingsFound.push_back(node->scenarioID);
            return; // Don't traverse further from an ending
        }

        // Traverse left and right children
        traverseTree(node->left);
        traverseTree(node->right);
    }

public:
    bool validateTree(DecisionTree& tree) {
        // Clear previous results
        visitedNodes.clear();
        endingsFound.clear();

        // Start traversal from root
        DecisionNode* root = tree.getRoot();
        if (!root) {
            std::cout << "Error: Tree root is null!" << std::endl;
            return false;
        }

        traverseTree(root);

        // Print results
        std::cout << "Validation Results:" << std::endl;
        std::cout << "- Total unique nodes visited: " << visitedNodes.size() << std::endl;
        std::cout << "- Total endings found: " << endingsFound.size() << std::endl;

        if (visitedNodes.size() >= 20) {
            std::cout << "✓ Decision tree has 20+ nodes (" << visitedNodes.size() << ")" << std::endl;
        } else {
            std::cout << "✗ Decision tree has less than 20 nodes (" << visitedNodes.size() << ")" << std::endl;
        }

        if (endingsFound.size() >= 5) {
            std::cout << "✓ Game has 5+ endings (" << endingsFound.size() << ")" << std::endl;
        } else {
            std::cout << "✗ Game has less than 5 endings (" << endingsFound.size() << ")" << std::endl;
        }

        // Print all ending IDs
        std::cout << "Ending IDs: ";
        for (int id : endingsFound) {
            std::cout << id << " ";
        }
        std::cout << std::endl;

        return (visitedNodes.size() >= 20 && endingsFound.size() >= 5);
    }

    int getNodeCount() const {
        return visitedNodes.size();
    }

    int getEndingCount() const {
        return endingsFound.size();
    }
};

int main() {
    std::cout << "==================================" << std::endl;
    std::cout << "Wolf Pack Survival Game - Validator" << std::endl;
    std::cout << "==================================" << std::endl;

    // Create and build the decision tree
