    tree.buildSampleTree();

    // Validate the tree
    DecisionTreeValidator validator;
    bool isValid = validator.validateTree(tree);

    if (isValid) {
        std::cout << "✓ All validations passed!" << std::endl;
    } else {
        std::cout << "✗ Some validations failed!" << std::endl;
    }

    std::cout << "==================================" << std::endl;

